    "nt8(7) || 8;\n    st.cellH = v.getUint8(8"
    ") || 16;\n    if (cols && rows && (cols !"
    "== st.cols || rows !== st.rows)) {\n     "
    " st.cols = cols; st.rows = rows; resizeT"
    "ext();\n    }\n    if (st.surfW && st.surf"
    "H) resizePix(st.surfW, st.surfH);\n    re"
    "turn;\n  }\n\n  if (op === OP_ROW) {\n    co"
    "nst y = v.getUint8(1), n = v.getUint8(2)"
    ";\n    if (y >= st.rows) return;\n    for "
    "(let x = 0; x < n && x < st.cols; x++) {"
    "\n      st.cells[y * st.cols + x] =\n     "
    "   v.getUint8(3 + x * 2) | (v.getUint8(4"
    " + x * 2) << 8);\n    }\n    schedulePaint"
    "([y]);\n    showText();\n    return;\n  }\n\n"
    "  if (op === OP_CURSOR) {\n    const x = "
    "v.getUint8(1), y = v.getUint8(2);\n    co"
    "nst ch = v.getUint8(3), attr = v.getUint"
    "8(4), on = v.getUint8(5) !== 0;\n    cons"
    "t was = { x: st.cur.x, y: st.cur.y };\n  "
    "  if (y < st.rows && x < st.cols) st.cel"
    "ls[y * st.cols + x] = ch | (attr << 8);\n"
    "    st.cur = { x, y, on };\n    scheduleP"
    "aint([was.y, y]);\n    showText();\n    re"
    "turn;\n  }\n\n  if (op === OP_RAW || op ==="
    " OP_PACK || op === OP_IDX) {\n    band(op"
    ", v, 1, v.byteLength);\n  }\n}\n\nfunction s"
    "end(bytes) {\n  if (st.ws && st.ws.readyS"
    "tate === 1) st.ws.send(new Uint8Array(by"
    "tes));\n}\n\n/* ---- keys -----------------"
    "----------------------------------------"
    "---- */\n\nfunction sendKey(kind, hid, uni"
    "code, mods) {\n  const m = (mods === unde"
    "fined ? st.sticky : mods);\n  send([IN_KE"
    "Y, kind, m, hid & 255, hid >> 8, unicode"
    " & 255,\n        (unicode >> 8) & 255, 0]"
    ");\n}\n\nfunction tap(hid) {\n  sendKey(1, h"
    "id, 0);\n  sendKey(2, hid, 0);\n  clearSti"
    "cky();\n}\n\nfunction clearSticky() {\n  if "
    "(!st.sticky) return;\n  st.sticky = 0;\n  "
    "for (const b of ui.keys.querySelectorAll"
    "(\"button.held\")) {\n    b.classList.remov"
    "e(\"held\");\n  }\n}\n\n/*\n * The bar of keys "
    "a phone's own keyboard does not have.\n *"
    "\n * Ctrl and Alt latch rather than repea"
    "t: there is no way to hold one down and\n"
    " * press a letter on a touch screen, so "
    "a tap arms it for the next keystroke and"
    "\n * the keystroke clears it.  That is ho"
    "w every terminal application on a phone\n"
    " * has to do it, and it is the reason Ct"
    "rl+C from here reaches the shell at all."
    "\n */\nconst KEYBAR = [\n  [\"Esc\", () => ta"
    "p(K.esc)],\n  [\"Tab\", () => tap(K.tab)],\n"
    "  [\"Ctrl\", \"mod\", MOD.ctrl],\n  [\"Alt\", \""
    "mod\", MOD.alt],\n  [\"\342\206\221\", () => tap(K.up"
    ")],\n  [\"\342\206\223\", () => tap(K.down)],\n  [\"\342\206"
    "\220\", () => tap(K.left)],\n  [\"\342\206\222\", () => "
    "tap(K.right)],\n  [\"\342\217\216\", () => tap(K.ent"
    "er)],\n  [\"\342\214\253\", () => tap(K.back)],\n  [\""
    "Home\", () => tap(K.home)],\n  [\"End\", () "
    "=> tap(K.end)],\n  [\"PgUp\", () => tap(K.p"
    "gup)],\n  [\"PgDn\", () => tap(K.pgdn)],\n  "
    "[\"Del\", () => tap(K.del)],\n  [\"F1\", () ="
    "> tap(K.f1)], [\"F2\", () => tap(K.f2)], ["
    "\"F3\", () => tap(K.f3)],\n  [\"F4\", () => t"
    "ap(K.f4)], [\"F5\", () => tap(K.f5)], [\"F6"
    "\", () => tap(K.f6)],\n  [\"F7\", () => tap("
    "K.f7)], [\"F8\", () => tap(K.f8)], [\"F9\", "
    "() => tap(K.f9)],\n  [\"F10\", () => tap(K."
    "f10)], [\"F11\", () => tap(K.f11)], [\"F12\""
    ", () => tap(K.f12)],\n];\n\nfor (const item"
    " of KEYBAR) {\n  const b = document.creat"
    "eElement(\"button\");\n  b.textContent = it"
    "em[0];\n  if (item[1] === \"mod\") {\n    co"
    "nst bit = item[2];\n    b.onclick = () =>"
    " {\n      st.sticky ^= bit;\n      b.class"
    "List.toggle(\"held\", (st.sticky & bit) !="
    "= 0);\n    };\n  } else {\n    b.onclick = "
    "item[1];\n  }\n  ui.keys.appendChild(b);\n}"
    "\n\nui.kb.onclick = () => {\n  ui.sink.focu"
    "s();\n  ui.sink.value = \"\";\n};\n\n/*\n * A p"
    "hone's keyboard reports characters, not "
    "keys.  Two paths, and both are\n * needed"
    ": `keydown` carries the named keys on an"
    "ything with a real keyboard and\n * often"
    " nothing useful on a touch one, while th"
    "e hidden textarea's `input`\n * event car"
    "ries what was actually composed - includ"
    "ing anything past ASCII,\n * which has no"
    " HID usage to be named by.\n */\nconst BY_"
    "CODE = {\n  Escape: K.esc, Tab: K.tab, En"
    "ter: K.enter, Backspace: K.back,\n  Arrow"
    "Up: K.up, ArrowDown: K.down, ArrowLeft: "
    "K.left, ArrowRight: K.right,\n  Home: K.h"
    "ome, End: K.end, PageUp: K.pgup, PageDow"
    "n: K.pgdn, Delete: K.del,\n  Space: K.spa"
    "ce,\n};\nfor (let i = 1; i <= 12; i++) BY_"
    "CODE[\"F\" + i] = K[\"f\" + i];\n\nwindow.addE"
    "ventListener(\"keydown\", (e) => {\n  let m"
    "ods = 0;\n  if (e.shiftKey) mods |= MOD.s"
    "hift;\n  if (e.ctrlKey) mods |= MOD.ctrl;"
    "\n  if (e.altKey) mods |= MOD.alt;\n  if ("
    "e.metaKey) mods |= MOD.gui;\n  mods |= st"
    ".sticky;\n\n  let hid = BY_CODE[e.code] ||"
    " 0;\n  if (!hid && /^Key[A-Z]$/.test(e.co"
    "de)) hid = K[e.code[3].toLowerCase()];\n "
    " if (!hid && /^Digit[0-9]$/.test(e.code)"
    ") hid = K[e.code[5]];\n\n  const uni = (e."
    "key && e.key.length === 1) ? e.key.codeP"
    "ointAt(0) : 0;\n  if (!hid && !uni) retur"
    "n;\n\n  e.preventDefault();\n  sendKey(1, h"
    "id, (mods & MOD.ctrl) ? 0 : uni, mods);\n"
    "  sendKey(2, hid, 0, mods);\n  clearStick"
    "y();\n});\n\nui.sink.addEventListener(\"inpu"
    "t\", () => {\n  const text = ui.sink.value"
    ";\n  ui.sink.value = \"\";\n  if (!text) ret"
    "urn;\n  /*\n   * With Ctrl or Alt armed th"
    "is is not text, it is a chord: the shell"
    " wants\n   * Ctrl+C as a keystroke with a"
    " keycode, not as the letter c.\n   */\n  i"
    "f (st.sticky && text.length === 1) {\n   "
    " const c = text.toLowerCase();\n    const"
    " hid = K[c] || 0;\n    if (hid) { tap(hid"
    "); return; }\n  }\n  send([IN_TEXT, ...new"
    " TextEncoder().encode(text)]);\n  clearSt"
    "icky();\n});\n\nui.sink.addEventListener(\"b"
    "eforeinput\", (e) => {\n  if (e.inputType "
    "=== \"deleteContentBackward\") { e.prevent"
    "Default(); tap(K.back); }\n  if (e.inputT"
    "ype === \"insertLineBreak\") { e.preventDe"
    "fault(); tap(K.enter); }\n});\n\n/* ---- th"
    "e pointer ------------------------------"
    "------------------------ */\n\n/*\n * Where"
    " a touch lands, in the pixels the board "
    "measures a pointer in.\n *\n * Two differe"
    "nt surfaces and the board says which is "
    "live: an application's,\n * whose size ar"
    "rived with the picture, and the console'"
    "s, which has no pixels\n * of its own and"
    " is measured in cells times the cell siz"
    "e the kernel draws\n * with.  Getting thi"
    "s wrong is the bug that put the cursor b"
    "elow the stylus on\n * the board's own to"
    "uchscreen for a week, so it is computed "
    "from what the board\n * said rather than "
    "from what looks right.\n */\nfunction wher"
    "e(ev) {\n  const cv = (st.mode === \"pix\")"
    " ? ui.pix : ui.text;\n  const r = cv.getB"
    "oundingClientRect();\n  if (r.width === 0"
    " || r.height === 0) return null;\n\n  cons"
    "t fx = (ev.clientX - r.left) / r.width;\n"
    "  const fy = (ev.clientY - r.top) / r.he"
    "ight;\n  if (fx < 0 || fx > 1 || fy < 0 |"
    "| fy > 1) return null;\n\n  if (st.mode =="
    "= \"pix\") {\n    return [Math.floor(fx * s"
    "t.surfW), Math.floor(fy * st.surfH)];\n  "
    "}\n  const col = Math.min(st.cols - 1, Ma"
    "th.floor(fx * st.cols));\n  const row = M"
    "ath.min(st.rows - 1, Math.floor(fy * st."
    "rows));\n  return [col * st.cellW, row * "
    "st.cellH];\n}\n\nfunction sendPtr(kind, ev,"
    " buttons) {\n  const p = where(ev);\n  if "
    "(!p) return;\n  send([IN_PTR, kind, butto"
    "ns, p[0] & 255, (p[0] >> 8) & 255,\n     "
    "   p[1] & 255, (p[1] >> 8) & 255, 0]);\n}"
    "\n\nfor (const cv of [ui.text, ui.pix]) {\n"
    "  cv.addEventListener(\"pointerdown\", (e)"
    " => {\n    e.preventDefault();\n    cv.set"
    "PointerCapture(e.pointerId);\n    st.ptrD"
    "own = true;\n    sendPtr(1, e, 1);\n  });\n"
    "  cv.addEventListener(\"pointermove\", (e)"
    " => {\n    if (!st.ptrDown) return;\n    e"
    ".preventDefault();\n    sendPtr(3, e, 1);"
    "\n  });\n  cv.addEventListener(\"pointerup\""
    ", (e) => {\n    if (!st.ptrDown) return;\n"
    "    e.preventDefault();\n    st.ptrDown ="
    " false;\n    sendPtr(2, e, 0);\n  });\n  cv"
    ".addEventListener(\"pointercancel\", () =>"
    " { st.ptrDown = false; });\n  cv.addEvent"
    "Listener(\"contextmenu\", (e) => e.prevent"
    "Default());\n}\n\n/*\n * Coming back from a "
    "locked screen.  The socket is usually de"
    "ad by then and the\n * browser has not no"
    "ticed, so ask for everything: the board "
    "answers 'H' by\n * resending the geometry"
    " and marking the whole screen as owed.\n "
    "*/\ndocument.addEventListener(\"visibility"
    "change\", () => {\n  if (document.visibili"
    "tyState !== \"visible\") return;\n  if (!st"
    ".ws || st.ws.readyState !== 1) { connect"
    "(); return; }\n  send([IN_HELLO]);\n});\n\nr"
    "esizeText();\nconnect();\n</script>\n";

#endif /* AG_PHONE_PAGE_H */
